BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(24);
SELECT ok(to_regprocedure('app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)') IS NOT NULL,'private exact-forward policy candidate source exists');
SELECT ok((SELECT count(*)=1 FROM pg_proc p JOIN pg_roles r ON r.oid=p.proowner WHERE p.oid='app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)'::regprocedure AND r.rolname='schoolos_schema_owner'),'fixed private schema owner owns the candidate source');
SELECT ok((SELECT prosecdef=false FROM pg_proc WHERE oid='app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)'::regprocedure),'candidate is security invoker');
SELECT ok((SELECT provolatile='v' FROM pg_proc WHERE oid='app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)'::regprocedure),'candidate observes current sources at call time');
SELECT ok((SELECT proconfig @> ARRAY['search_path=pg_catalog,pg_temp'] FROM pg_proc WHERE oid='app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)'::regprocedure),'candidate fixes a private safe search path');
SELECT ok(NOT has_function_privilege('anon','app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)','EXECUTE'),'anon cannot select a candidate');
SELECT ok(NOT has_function_privilege('authenticated','app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)','EXECUTE'),'clients cannot select a candidate');
SELECT ok(NOT has_function_privilege('service_role','app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)','EXECUTE'),'service role cannot call private candidate');
SELECT ok(NOT has_function_privilege('schoolos_workflow_executor','app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)','EXECUTE'),'workflow role cannot call the candidate');
SELECT ok(NOT has_function_privilege('schoolos_file_login','app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)','EXECUTE'),'file worker cannot call the candidate');
SELECT ok(NOT has_function_privilege('schoolos_platform_executor','app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)','EXECUTE'),'platform executor cannot call the candidate');
SELECT ok(NOT has_function_privilege('schoolos_identity_executor','app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)','EXECUTE'),'identity executor cannot call the candidate');
SELECT ok(NOT has_function_privilege('schoolos_student_executor','app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)','EXECUTE'),'Student executor cannot call the candidate');
SELECT ok(NOT has_function_privilege('schoolos_evidence_writer','app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)','EXECUTE'),'evidence writer cannot call the candidate');
SELECT ok((SELECT pg_get_functiondef(oid) NOT ILIKE '%INSERT INTO%' AND pg_get_functiondef(oid) NOT ILIKE '%UPDATE app_private%' AND pg_get_functiondef(oid) NOT ILIKE '%DELETE FROM%' FROM pg_proc WHERE oid='app_private.db03_policy_binding_candidate_source(uuid,bigint,uuid)'::regprocedure),'candidate has no database write operations');
SELECT ok(app_private.db03_policy_binding_candidate_source(NULL,1,'00000000-0000-0000-0000-000000000001'::uuid) IS NULL,'null application never creates a policy binding');
SELECT ok(app_private.db03_policy_binding_candidate_source('00000000-0000-0000-0000-000000000002'::uuid,1,'00000000-0000-0000-0000-000000000001'::uuid) IS NULL,'missing application has no policy candidate');
SELECT throws_ok($q$SELECT app_private.db03_policy_binding_candidate_source(NULL,0,'00000000-0000-0000-0000-000000000001'::uuid)$q$,'P0001','DB03 policy binding candidate typed source invalid','zero expected version is rejected');
SELECT throws_ok($q$SELECT app_private.db03_policy_binding_candidate_source(NULL,1,NULL)$q$,'P0001','DB03 policy binding candidate typed source invalid','missing Forward ID is rejected');
SELECT ok((SELECT count(*)=0 FROM app_private.admission_application_policy_snapshots),'candidate has not written a policy snapshot');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_policy_snapshot_mutation_disabled' AND NOT tgisinternal AND tgenabled='O'),'P44 deny-all snapshot writer remains active');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conname='db03_unsubmitted_policy_null' AND conrelid='app_private.admission_applications'::regclass),'S5 draft policy projection remains fail closed');
SELECT ok(to_regprocedure('app.bind_admission_application_policy(uuid,bigint,uuid,text)') IS NULL,'no active client policy binding command is exposed');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'Principal approval and Student creation remain disabled');
SELECT * FROM finish();
ROLLBACK;
